+            const auto output_dtype  = py::cast<std::string>(combine.attr("output_dtype"));
+            if (fp32_partial_ ? partial_dtype != "float32"
+                              : ((!quantized_ && partial_dtype != output_dtype) ||
+                                 (partial_dtype != "float16" && partial_dtype != "bfloat16")))
+                invalid("native split binding requires matching half or FP32 partials");
+            const int64_t partial_bytes = fp32_partial_ ? 4 : 2;
+            combine_fn_                 = combine.attr("fn");
+            combine_owner_              = combine.attr("owner");
+            has_lse_                    = py::cast<bool>(combine.attr("has_stats"));
+            lse_offset_                 = py::cast<int64_t>(combine.attr("lse_offset"));
+            auto partial_o = combine.attr("o"), partial_lse = combine.attr("lse");
+            auto os              = py::cast<std::array<int64_t, 4>>(partial_o.attr("strides"));
+            partial_o_strides_   = py::make_tuple(os[0], os[2], os[1]);
+            partial_lse_strides_ = py::cast<py::tuple>(partial_lse.attr("strides"));
+            const auto rows      = multiply(multiply(split_, b_), multiply(qh_, sq_));
+            if (lse_offset_ < multiply(multiply(rows, d_v_), partial_bytes) || lse_offset_ % 16)
+                invalid("invalid native split workspace layout");
+            workspace_bytes_ = add(lse_offset_, multiply(rows, 4));
+        }
+        // Plain sdpa may retain half Q/O while the compiled kernel reads FP8 K/V.
+        // Cache each port's declared type; runtime binding still checks it exactly.
+        for (size_t i = Q; i <= O; ++i) {
+            const auto dtype    = i == O && split_ > 1 ? py::cast<std::string>(combine.attr("output_dtype"))
+                                                       : py::cast<std::string>(expect[names[i]]);
+            const bool fp8      = dtype == "float8_e4m3fn" || dtype == "float8_e5m2";
+            const bool packed_o = i == O && block_output_ && output_pack_ == 2 && dtype == "uint8";
+            if (i == O && block_output_ && !(output_pack_ == 2 ? packed_o : fp8))
+                invalid("block-scaled O dtype does not match its compiled packing");
+            if ((quantized_ && i != O && !(pv_bf16_ && i == V))
+                    ? !fp8
+                    : (!packed_o && dtype != "float16" && dtype != "bfloat16" &&
+                       !(fp8 && (quantized_ || i == K || i == V))))
+                invalid("native dense binding has an unsupported operand dtype");
+            dtype_code_[i] = packed_o ? kDLUInt
+                             : fp8    ? (dtype == "float8_e4m3fn" ? kDLFloat8_e4m3fn : kDLFloat8_e5m2)
+                                      : (dtype == "float16" ? kDLFloat : kDLBfloat);
+            dtype_bits_[i] = packed_o || fp8 ? 8 : 16;
+        }
+        // The epilogue gate: the Rubin d256 bodies over dense K/V (half, per-tensor FP8 with a bf16 G, MXFP8) and the
+        // shared SM100 d256 half body over PAGED pools (dense queries past the decode tile; the paged gate).  A split
+        // (the gate rides the combine there), a ragged-Q leg and a block-scaled O keep refusing it.
+        has_gate_ = !spec.attr("gate_expect").is_none();
+        if (has_gate_) {
+            const auto dtype = py::cast<std::string>(spec.attr("gate_expect"));
+            if ((dtype != "float16" && dtype != "bfloat16") ||
+                (quantized_ ? dtype != "bfloat16" : dtype != py::cast<std::string>(expect["q"])) || split_ != 1 ||
+                ragged_ || block_output_ || dq != 256 || dv != 256 || (paged_ && quantized_))
+                invalid(
+                    "native epilogue gate requires an unsplit D256 half/BF16-gate plan (dense K/V, or paged pools with "
+                    "half "
+                    "operands)");
+            gate_code_ = dtype == "float16" ? kDLFloat : kDLBfloat;
+        }
+        auto order = py::cast<std::vector<std::string>>(spec.attr("order"));
+        if (order.size() != template_.size()) invalid("native dense host template has the wrong size");
+        for (size_t slot = 0; slot < NumSlots; ++slot) {
+            auto found = std::find(order.begin(), order.end(), slot_names[slot]);
+            if (slot == Scale && found == order.end()) found = std::find(order.begin(), order.end(), "scale_softmax");
+            // SM107 D256 and SM120 have no paged slots. SM120 half partials
+            // use o_ptr; only FP32 partials require the separate output slot.
+            const bool paged_slot = slot >= KTablePtr && slot <= NPages;
+            if (found == order.end() && slot != VTableStrides && !(slot == PartialOPtr && !fp32_partial_) &&
+                !(paged_slot && !paged_) && !(slot == RaggedQPtr && !ragged_) &&
+                !((slot == GatePtr || slot == GateStrides) && !has_gate_))
+                invalid(std::string("native dense host has no argument ") + slot_names[slot]);
+            index_[slot] = static_cast<size_t>(found - order.begin());
+        }
+        if (quantized_) {
+            for (size_t role = first_scalar_role(); role <= AmaxO; ++role) {
+                const auto name = std::string(names[role]) + "_ptr";
+                auto found      = std::find(order.begin(), order.end(), name);
+                if (found == order.end()) invalid("native dense FP8 host has no argument " + name);
+                quant_indices_[role - DescaleQ] = static_cast<size_t>(found - order.begin());
+            }
+            if (split_ > 1 && quant_offset_ < workspace_bytes_)
+                invalid("native dense FP8 split requires partial slabs before scalar scratch");
+            if (block_output_) {
+                const auto found = std::find(order.begin(), order.end(), "sf_o_ptr");
+                if (found == order.end()) invalid("block-scaled output host is missing sf_o_ptr");
+                block_index_ = static_cast<size_t>(found - order.begin());
+            }
+        }
+        auto prep          = py::module_::import_("cudnn.sdpa.fwd.prepared");
+        dense_layout_      = prep.attr("_dense_role_layout");
+        pool_layout_       = prep.attr("_paged_pool_layout");
+        table_layout_      = prep.attr("_paged_table_layout");
+        lse_layout_        = prep.attr("_dense_lse_layout");
+        packed_layout_     = prep.attr("_packed_role_layout");
+        ragged_lse_layout_ = prep.attr("_ragged_lse_layout");
+    }
+    py::tuple
+    bind(const py::handle &pack, const std::vector<int64_t> &indices, py::object stream) {
+        if (quantized_) invalid("FP8 binding needs a workspace and bind_quantized");
+        if (split_ != 1) invalid("split decode needs a workspace and bind_split");
+        return bind_launch(pack, indices, std::move(stream), 0).first;
+    }
+    py::object
+    bind_split(const py::handle &pack, const std::vector<int64_t> &indices, int64_t workspace, py::object stream) {
+        if (split_ == 1) invalid("bind_split requires a split decode plan");
+        auto bound = bind_launch(pack, indices, std::move(stream), workspace);
+        if (bound.first.size() == 0) return py::none();
+        return py::make_tuple(bound.first, bound.second);
+    }
+    py::tuple
+    bind_quantized(const py::handle &pack, const std::vector<int64_t> &indices, int64_t workspace, py::object stream) {
+        if (!quantized_) invalid("bind_quantized requires a per-tensor FP8 plan");
+        auto bound = bind_launch(pack, indices, std::move(stream), workspace);
+        return py::make_tuple(bound.first, bound.second, bound.identity);
+    }
+    BoundLaunch
+    bind_launch(const py::handle &pack, const std::vector<int64_t> &indices, py::object stream, int64_t workspace) {
+        if (indices.size() != (block_output_ ? NumRoles
+                               : mx_scales_  ? MxNumRoles
+                                             : (quantized_ ? PerTensorNumRoles : HalfNumRoles)))
+            invalid("native dense binding has the wrong number of role indices");
+        auto facts = read_native_operand_views(pack, indices);
+        if (block_output_ && output_pack_ == 2 && facts[O].filled && facts[O].dtype.code == kDLFloat4_e2m1fn &&
+            facts[O].dtype.bits == 4 && facts[O].dtype.lanes == 2) {
+            // The observer already normalized FP4 metadata to byte slots.
+            // Change only its storage type, never divide shape/strides twice.
+            facts[O].dtype = DLDataType{static_cast<uint8_t>(kDLUInt), 8, 1};
+        }
+        if (split_ > 1) {
+            // Adapters check observed workspace bytes; arithmetic is checked here
+            // before either launch, including the ragged early no-work return.
+            if (workspace <= 0 || workspace % 16) invalid("split workspace must be non-null and 16-byte aligned");
+            add(workspace, workspace_bytes_);
+        }
+        py::list frame(template_);
+        BoundGeometry q, o;
+        int64_t b, sq, q_cap = 0, o_cap = 0, lse_cap = 0;
+        py::tuple ragged_offsets;
+        if (ragged_) {
+            // Match the packed path's early no-work contract: validate Q/O/Stats
+            // geometry and current capacity before reading offsets or K/V roles.
+            operand(facts[Q], Q, dtype_code_[Q], 16, 16);
+            operand(facts[O], O, dtype_code_[O], 16, 2);
+            q     = layout(facts[Q], Q, b_, sq_);
+            o     = layout(facts[O], O, b_, sq_);
+            q_cap = packed_capacity(facts[Q], q, Q);
+            o_cap = packed_capacity(facts[O], o, O);
+            b     = b_;
+            sq    = sq_;
+            if (has_lse_) {
+                operand(facts[LSE], LSE, kDLFloat, 32, 4);
+                auto lse = layout(facts[LSE], LSE, b, sq);
+                lse_cap  = packed_capacity(facts[LSE], lse, LSE);
+                put(frame, LSEPtr, py::int_(facts[LSE].pointer));
+                put(frame, LSEStrides, lse.bound);
+            } else {
+                if (facts[LSE].filled) invalid("this specialization was compiled without a Stats output");
+                put(frame, LSEPtr, py::none());
+                put(frame, LSEStrides, py::make_tuple(0, 0, 0));
+            }
+            if (has_total_q_ && (o_cap < total_q_ || (has_lse_ && lse_cap < total_q_)))
+                invalid("packed O and Stats must cover the declared packed Q total");
+            if (!q_cap || !o_cap || !facts[O].pointer || (has_lse_ && (!lse_cap || !facts[LSE].pointer)))
+                return {py::tuple(), py::tuple()};
+            ragged_offsets = py::make_tuple(offsets(facts[RaggedQ], RaggedQ),
+                                            offsets(facts[RaggedO], RaggedO),
+                                            has_lse_ ? py::cast(offsets(facts[RaggedLSE], RaggedLSE)) : py::none());
+            put(frame, RaggedQPtr, py::borrow<py::object>(ragged_offsets[0]));
+            if (has_total_q_) q_cap = std::min(q_cap, std::max<int64_t>(total_q_, 0));
+            put(frame, QPtr, py::int_(facts[Q].pointer));
+            put(frame, QStrides, py::make_tuple(q.extent0, q.extent0, q.extent1));
+            for (size_t i : {static_cast<size_t>(K), static_cast<size_t>(V)}) {
+                operand(facts[i], i, dtype_code_[i], dtype_bits_[i], 16);
+                put(frame, static_cast<Slot>(QPtr + i), py::int_(facts[i].pointer));
+            }
+        } else {
+            for (size_t i = Q; i <= O; ++i) {
+                operand(facts[i], i, dtype_code_[i], dtype_bits_[i], i == O && split_ > 1 ? dtype_bits_[i] / 8 : 16);
+                put(frame, static_cast<Slot>(QPtr + i), py::int_(facts[i].pointer));
+            }
+            q  = geometry(facts[Q], Q);
+            o  = geometry(facts[O], O);
+            b  = q.extent0;
+            sq = q.extent1;
+            if (split_ > 1 && (b != b_ || sq != sq_))
+                invalid("a split launch runs the declared batch and query extents");
+            if (o.extent0 != b || o.extent1 != sq)
+                invalid(split_ > 1 ? "split output must match the declared batch and query extents"
+                                   : "o must match q batch and sequence extents");
+            put(frame, QStrides, q.bound);
+            put(frame, OStrides, o.bound);
+        }
+        int64_t sk;
+        auto k = geometry(facts[K], K), v = geometry(facts[V], V);
+        put(frame, KStrides, k.bound);
+        put(frame, VStrides, v.bound);
+        if (paged_) {
+            auto kt = table(facts[KTable], KTable, b), vt = table(facts[VTable], VTable, b);
+            if (kt.extent1 != vt.extent1) invalid("K and V page tables must share max_pages");
+            if (k.extent0 != v.extent0) invalid("K and V pools must hold the same number of pages");
+            if (index_[VTableStrides] == template_.size() && !kt.bound.equal(vt.bound))
+                invalid("this prepared host requires matching K/V table strides");
+            sk = multiply(kt.extent1, page_size_);
+            put(frame, KTablePtr, py::int_(facts[KTable].pointer));
+            put(frame, VTablePtr, py::int_(facts[VTable].pointer));
+            put(frame, KTableStrides, kt.bound);
+            if (index_[VTableStrides] != template_.size()) put(frame, VTableStrides, vt.bound);
+            put(frame, NPages, py::int_(k.extent0));
+        } else {
+            if (k.extent0 != b || v.extent0 != b || k.extent1 != v.extent1)
+                invalid("k / v must match q batch and share sequence extent");
+            sk = k.extent1;
+        }
+        if (shape_fixed_ && (sq != sq_ || sk != sk_))
+            invalid("this artifact was lowered for exactly S_q=" + std::to_string(sq_) +
+                    ", S_kv=" + std::to_string(sk_) +
+                    " (a square-mask / schedule canonicalization read the declared extents); "
+                    "it does not serve (" +
+                    std::to_string(sq) + ", " + std::to_string(sk) + ")");
+        if (lpt_fixed_ && (b != b_ || sq != sq_))
+            invalid("this artifact's grouped LPT schedule was compiled for exactly batch=" + std::to_string(b_) +
+                    ", S_q=" + std::to_string(sq_) + "; it does not serve batch=" + std::to_string(b) +
+                    ", S_q=" + std::to_string(sq));
+        if (!(tail_native_ || paged_ || sk % tile_n_ == 0 || seq_kv_ ||
+              (causal_ && ((bottom_right_ && window_right_ == 0) || (!bottom_right_ && window_right_ <= sk - sq)))))
+            invalid("S_kv (" + std::to_string(sk) + ") must be a multiple of " + std::to_string(tile_n_) +
+                    " for this artifact unless per-batch KV lengths are present or the causal mask covers the KV tail "
+                    "(the compiled specialization does not mask a partial last tile)");
+        put(frame, ProblemSize, py::make_tuple(b, qh_, kh_, sq, sk, q_cap));
+        if (!ragged_ && has_lse_) {
+            operand(facts[LSE], LSE, kDLFloat, 32, 4);
+            auto lse = layout(facts[LSE], LSE, b, sq);
+            check_span(facts[LSE], lse.need, LSE);
+            put(frame, LSEPtr, py::int_(facts[LSE].pointer));
+            put(frame, LSEStrides, lse.bound);
+        } else if (!ragged_) {
+            if (facts[LSE].filled) invalid("this specialization was compiled without a Stats output");
+            put(frame, LSEPtr, py::none());
+            put(frame, LSEStrides, py::make_tuple(0, 0, 0));
+        }
+        if (has_sink_) {
+            operand(facts[Sinks], Sinks, kDLFloat, 32, 4);
+            if (contiguous_elements(facts[Sinks], Sinks) != qh_) invalid("sinks must have exactly H_q elements");
+            check_span(facts[Sinks], qh_, Sinks);
+            put(frame, SinksPtr, py::int_(facts[Sinks].pointer));
+        } else {
+            if (facts[Sinks].filled) invalid("this specialization was compiled without a sink");
+            put(frame, SinksPtr, py::int_(0));
+        }
+        if (has_gate_) {
+            operand(facts[Gate], Gate, gate_code_, 16, 16);
+            const auto gate = geometry(facts[Gate], Gate);
+            if (gate.extent0 != b || gate.extent1 != sq) invalid("gate must match q batch and sequence extents");
+            if (!facts[Gate].pointer) invalid("gate must have a non-null address");
+            add(facts[Gate].pointer, multiply(gate.need, 2));
+            put(frame, GatePtr, py::int_(facts[Gate].pointer));
+            put(frame, GateStrides, gate.bound);
+        } else if (facts[Gate].filled) {
+            invalid("this specialization was compiled without an epilogue gate");
+        }
+        put(frame, ODescPtr, py::int_(0));
+        put(frame, MetaPtr, py::int_(seq_kv_ ? lengths(facts[KVLens], KVLens, b) : 0));
+        const int64_t q_lens_address = seq_q_ ? lengths(facts[QLens], QLens, b + (ragged_q_lens_ == 2 ? 1 : 0)) : 0;
+        if (seq_q_) put(frame, QLensPtr, py::int_(q_lens_address));
+        put(frame, Stream, stream);
+        py::tuple combine_frame;
+        if (split_ > 1) {
+            if (!quantized_) {
+                const auto end = add(workspace, workspace_bytes_);
+                for (size_t role = Q; role < facts.size(); ++role) {
+                    const auto &f = facts[role];
+                    if (!f.filled) continue;
+                    const auto bytes = storage_span(f);
+                    if (bytes && workspace < add(f.pointer, bytes) && f.pointer < end)
+                        invalid("split workspace overlaps " + std::string(names[role]));
+                }
+            }
+            const auto partial_lse = add(workspace, lse_offset_);
+            auto os                = py::cast<std::array<int64_t, 3>>(o.bound);
+            // The combine entry's positional frame (split_combine.compile_ptr): the
+            // dense base, the ragged-Q leg's offsets / divisors / capacities, the
+            // half flavors' fp32 [H] sink pointer (has_sink entries), the int32 [B] Q lengths of a split sink over
+            // padded queries, then the stream.
+            py::list cf;
+            cf.append(workspace);
+            cf.append(partial_lse);
+            cf.append(facts[O].pointer);
+            cf.append(frame[index_[LSEPtr]]);
+            cf.append(py::make_tuple(b_, qh_, sq_, d_v_));
+            cf.append(split_);
+            cf.append(py::make_tuple(os[0], os[1], os[2], 1));
+            cf.append(frame[index_[LSEStrides]]);
+            if (ragged_) {
+                const int64_t max_tokens = std::numeric_limits<int32_t>::max();
+                cf.append(ragged_offsets[0]);
+                cf.append(ragged_offsets[1]);
+                cf.append(ragged_offsets[2]);
+                cf.append(ragged_divs_);
+                cf.append(py::make_tuple(std::min(o_cap, max_tokens), std::min(lse_cap, max_tokens)));
+            }
+            // Quantized optional sink operands trail that entry's stream; its
+            // scalar binding below appends them after Amax/scale are bound.
+            if (has_sink_ && !quantized_) cf.append(facts[Sinks].pointer);
+            if (combine_q_lens_ && !quantized_) cf.append(q_lens_address);
+            cf.append(stream);
+            if (ragged_q_lens_) cf.append(q_lens_address);
+            combine_frame = py::tuple(cf);
+            put(frame, OPtr, py::int_(workspace));
+            if (fp32_partial_) put(frame, PartialOPtr, py::int_(workspace));
+            put(frame, OStrides, partial_o_strides_);
+            put(frame, LSEPtr, py::int_(partial_lse));
+            put(frame, LSEStrides, partial_lse_strides_);
+        }
+        const auto identity = quantized_ ? bind_quantized_scalars(facts, frame, combine_frame, workspace, stream) : 0;
+        return {py::tuple(frame), combine_frame, identity};
+    }
+    bool
+    execute(const py::handle &pack,
+            const std::vector<int64_t> &indices,
+            py::object stream,
+            py::object scale  = py::none(),
+            int64_t workspace = 0) {
+        auto bound  = bind_launch(pack, indices, stream, workspace);
+        auto &frame = bound.first;
+        if (frame.size() == 0) return false;
+        if (!scale.is_none()) {
+            py::list args(frame);
+            put(args, Scale, std::move(scale));
+            frame = py::tuple(args);
+        }
+        if (bound.identity) fill_word_(bound.identity, 1, 0x3f800000, py::int_(stream));
+        auto result = py::steal<py::object>(PyObject_CallObject(fn_.ptr(), frame.ptr()));
+        if (!result) throw py::python_error();
+        if (split_ > 1) {
+            auto combined = py::steal<py::object>(PyObject_CallObject(combine_fn_.ptr(), bound.second.ptr()));
+            if (!combined) throw py::python_error();
+        }
+        return true;
+    }
+    py::object
+    execute_ordered(py::handle schema,
+                    py::handle buffers,
+                    py::handle tensor_uids,
+                    const py::dict &auto_bindings,
+                    py::handle workspace,
+                    py::handle override_uids,
+                    py::handle override_shapes,
+                    py::handle override_strides,
+                    const std::vector<int64_t> &indices,
+                    py::object stream) {
+        auto read = read_ordered_binding(
+            schema, buffers, tensor_uids, auto_bindings, workspace, override_uids, override_shapes, override_strides);
+        // Supplied workspace is observed even when this bounded plan needs no
+        // scratch. Python completes unsupported producer protocols before the
+        // same binder runs; malformed buffers never trigger another executor.
+        if (quantized_ || split_ > 1 || !py::cast<py::list>(read[1]).empty() || read[2].is_none()) return read;
+        execute(read[0], indices, std::move(stream));
+        return py::none();
+    }
+
+   private:
+    size_t
+    first_scalar_role() const {
+        return !mx_scales_ ? DescaleQ : block_output_ && block_has_scale_ ? ScaleO : AmaxO;
+    }
+    static int64_t
+    storage_span(const NativeOperandView &f) {
+        if (f.observed_bytes >= 0) return f.observed_bytes;
+        if (!f.stride.empty() && f.stride.size() != f.shape.size())
+            invalid("operand shape and stride must have the same rank");
+        int64_t extent = 1, compact = 1;
+        bool empty = false;
+        for (size_t i = f.shape.size(); i-- > 0;) {
+            if (f.shape[i] < 0 || (!f.stride.empty() && f.stride[i] < 0))
+                invalid("operand geometry must be nonnegative");
+            empty |= f.shape[i] == 0;
+            if (f.shape[i]) extent = add(extent, multiply(f.shape[i] - 1, f.stride.empty() ? compact : f.stride[i]));
+            compact = multiply(compact, f.shape[i]);
+        }
+        return empty ? 0 : multiply(extent, (f.dtype.bits + 7) / 8);
+    }
+    void
+    bind_block_output(const std::vector<NativeOperandView> &facts, py::list &frame) const {
+        const auto &f = facts[SfO];
+        if (!f.filled) invalid("block-scaled output requires sf_o");
+        if (f.device_type != -1 && (f.device_type != kDLCUDA || f.device_id != device_))
+            invalid("sf_o must be on this plan's CUDA device");
+        if (f.dtype.bits != 8 || f.dtype.lanes != 1) invalid("sf_o requires byte storage");
+        SdpaMxScaleBinding::storage_bytes(f);  // validate dense physical storage, including axis permutations
+        if (f.observed_bytes >= 0 && f.observed_bytes < block_bytes_)
+            invalid("sf_o storage does not cover the compiled atom layout");
+        if (!f.pointer || f.pointer % 16) invalid("sf_o must be 16-byte aligned");
+        const auto end = add(f.pointer, block_bytes_);
+        for (size_t role = Q; role < facts.size(); ++role) {
+            const auto &other = facts[role];
+            if (role == SfO || !other.filled ||
+                std::find(other.shape.begin(), other.shape.end(), 0) != other.shape.end())
+                continue;
+            const auto bytes = storage_span(other);
+            if (bytes && f.pointer < add(other.pointer, bytes) && other.pointer < end)
+                invalid("sf_o overlaps " + std::string(names[role]));
+        }
+        frame[block_index_] = py::int_(f.pointer);
+    }
+    int64_t
+    bind_quantized_scalars(const std::vector<NativeOperandView> &facts,
+                           py::list &frame,
+                           py::tuple &combine,
+                           int64_t workspace,
+                           const py::object &stream) const {
+        if (!workspace || workspace % 16) invalid("prepared FP8 requires an aligned caller workspace");
+        const auto scratch = add(workspace, quant_offset_), identity = add(scratch, 4), end = add(identity, 4);
+        int64_t initialize_identity = 0;
+        std::array<int64_t, 5> pointers{};
+        for (size_t role = first_scalar_role(); role <= AmaxO; ++role) {
+            const auto &f = facts[role];
+            int64_t ptr;
+            if (!f.filled) {
+                ptr = role == AmaxO ? scratch : identity;
+                if (role != AmaxO) initialize_identity = identity;
+            } else {
+                operand(f, role, kDLFloat, 32, 4);
+                if (!f.pointer || contiguous_elements(f, role) != 1)
+                    invalid(std::string(names[role]) + " must be one aligned float32 device element");
+                check_span(f, 1, role);
+                if (role == AmaxO && !has_amax_) invalid("this specialization does not produce amax_o");
+                ptr = f.pointer;
+            }
+            pointers[role - DescaleQ]              = ptr;
+            frame[quant_indices_[role - DescaleQ]] = py::int_(ptr);
+        }
+        const auto amax = pointers[AmaxO - DescaleQ], amax_end = add(amax, 4);
+        if (facts[AmaxO].filled && workspace < amax_end && amax < end)
+            invalid("prepared FP8 workspace overlaps amax_o");
+        for (size_t role = Q; role < facts.size(); ++role) {
+            const auto &f = facts[role];
+            if (!f.filled || role == AmaxO) continue;
+            int64_t bytes = storage_span(f);
+            if (block_output_ && role == SfO) bytes = std::max(bytes, block_bytes_);
+            if (!bytes) continue;
+            const auto operand_end = add(f.pointer, bytes);
+            if (workspace < operand_end && f.pointer < end)
+                invalid("prepared FP8 workspace overlaps " + std::string(names[role]));
+            if (amax < operand_end && f.pointer < amax_end) invalid("amax_o overlaps " + std::string(names[role]));
+        }
+        if (mx_scales_) {
+            for (size_t role = DescaleQ; role <= ScaleO; ++role)
+                if (facts[role].filled && !(role == ScaleO && block_output_))
+                    invalid("MXFP8 plans do not consume per-tensor input scales");
+            if (block_output_ && facts[ScaleO].filled != block_has_scale_)
+                invalid("scale_o presence must match the block-output specialization");
+            mx_scales_->bind(facts, SfQ, &frame, false, paged_, b_, sq_, sk_, page_size_);
+        } else if (block_output_) {
+            for (size_t role = SfQ; role <= SfV; ++role)
+                if (facts[role].filled) invalid("per-tensor FP8 plans do not consume input scale factors");
+        }
+        if (block_output_) bind_block_output(facts, frame);
+        if (split_ > 1) {
+            py::list expanded(combine);
+            expanded[combine.size() - 1] = has_amax_ ? py::cast(amax) : py::none();
+            expanded.append(mx_scales_ ? py::none() : py::cast(pointers[ScaleO - DescaleQ]));
+            expanded.append(stream);
+            if (has_sink_) {
+                expanded.append(facts[Sinks].pointer);
+                expanded.append(combine_q_lens_ ? py::cast(lengths(facts[QLens], QLens, b_)) : py::none());
+            }
+            combine = py::tuple(expanded);
+            if (!mx_scales_ && dtype_bits_[O] == 8) frame[quant_indices_[ScaleO - DescaleQ]] = py::none();
+        }
+        return initialize_identity;
+    }
+    void
+    operand(const NativeOperandView &f, size_t role, int code, int bits, int alignment) const {
+        const std::string name = names[role];
+        if (!f.filled) invalid(name + " is required");
+        if (f.dtype.code != code || f.dtype.bits != bits || f.dtype.lanes != 1)
+            invalid(role == Sinks ? "sinks must be float32"
+                                  : name + ": runtime buffer dtype does not match its declaration");
+        if (f.device_type != -1 && (f.device_type != kDLCUDA || f.device_id != device_))
+            invalid(name + " must be on this plan's CUDA device");
+        if (quantized_ && (role == KTable || role == VTable) && (!f.pointer || f.pointer % alignment))
+            invalid(std::string(role == KTable ? "paged_attention_k_table" : "paged_attention_v_table") +
+                    " must have a non-null, 4-byte-aligned address");
+        if (f.pointer % alignment) invalid(name + ": runtime buffer address is misaligned");
+    }
+    static void
+    check_span(const NativeOperandView &f, int64_t need, size_t role) {
+        const int64_t width = (static_cast<int64_t>(f.dtype.bits) + 7) / 8;
+        if (f.observed_bytes >= 0 && f.observed_bytes / width < need)
+            invalid(std::string(names[role]) + ": observed storage is too small for its effective geometry");
+    }
+    BoundGeometry
+    layout(const NativeOperandView &f, size_t role, int64_t b = -1, int64_t sq = -1) {
+        auto &cached = geometry_[role];
+        if (cached.valid && cached.batch == b && cached.sequence == sq && !f.stride.empty() &&
+            std::equal(cached.shape.begin(), cached.shape.end(), f.shape.begin(), f.shape.end()) &&
+            std::equal(cached.strides.begin(), cached.strides.end(), f.stride.begin(), f.stride.end()))
+            return cached;
+        std::vector<int64_t> shape(f.shape.begin(), f.shape.end()), strides;
+        if (f.stride.empty()) {
+            strides.reserve(shape.size());
+            int64_t value = 1;
+            for (size_t i = shape.size(); i-- > 0;) {
+                strides.push_back(value);
+                value = multiply(value, shape[i]);
+            }
+            std::reverse(strides.begin(), strides.end());
+        } else {
+            strides.assign(f.stride.begin(), f.stride.end());
+        }
+        if (strides.size() != shape.size()) invalid("operand shape and stride must have the same rank");
+        if (cached.valid && cached.shape == shape && cached.strides == strides && cached.batch == b &&
+            cached.sequence == sq)
+            return cached;
+        Geometry result;
+        result.shape    = std::move(shape);
+        result.strides  = std::move(strides);
+        result.batch    = b;
+        result.sequence = sq;
+        auto sh = py::cast(result.shape), st = py::cast(result.strides);
+        // Python's lru_cache requires hashable arguments. These are allocated only
+        // for a new effective layout, never for the warm stable geometry.
+        auto shape_tuple = py::tuple(sh), stride_tuple = py::tuple(st);
+        if (ragged_ && (role == Q || role == O)) {
+            auto value = py::cast<std::array<int64_t, 3>>(
+                packed_layout_(shape_tuple, stride_tuple, qh_, d_v_, 2, role == Q, names[role]));
+            result.extent0 = value[0];
+            result.extent1 = value[1];
+            result.need    = value[2];
+            result.bound   = py::make_tuple(0, value[0], value[1]);
+        } else if (ragged_ && role == LSE) {
+            auto value =
+                py::cast<py::tuple>(ragged_lse_layout_(shape_tuple, stride_tuple, qh_, ragged_lse_head_major_));
+            auto head = py::cast<int64_t>(value[0]), token = py::cast<int64_t>(value[1]);
+            result.need    = py::cast<int64_t>(value[2]);
+            result.extent0 = py::cast<bool>(value[3]);
+            result.extent1 = head;
+            result.bound   = py::make_tuple(0, head, token);
+            if (result.extent0 && has_total_q_ && head < total_q_)
+                invalid("head-major ragged Stats head stride must cover the declared packed Q total");
+        } else if (role == LSE) {
+            auto value   = py::cast<py::tuple>(lse_layout_(shape_tuple, stride_tuple, b, sq, qh_));
+            result.bound = py::cast<py::tuple>(value[0]);
+            result.need  = py::cast<int64_t>(value[1]);
+        } else if (role == KTable || role == VTable) {
+            auto value     = py::cast<py::tuple>(table_layout_(shape_tuple, stride_tuple));
+            auto extents   = py::cast<std::array<int64_t, 2>>(value[0]);
+            result.extent0 = extents[0];
+            result.extent1 = extents[1];
+            result.bound   = py::cast<py::tuple>(value[1]);
+            if (result.extent0 < b) invalid("page table batch extent is smaller than q batch");
+            auto ts     = py::cast<std::array<int64_t, 2>>(result.bound);
+            result.need = add(add(multiply(b - 1, ts[0]), multiply(result.extent1 - 1, ts[1])), 1);
+        } else if (paged_ && (role == K || role == V)) {
+            auto value     = py::cast<py::tuple>(pool_layout_(shape_tuple,
+                                                          stride_tuple,
+                                                          dtype_bits_[role] / 8,
+                                                          role == V ? v_hnd_ : hnd_,
+                                                          kh_,
+                                                          page_size_,
+                                                          role == K ? d_qk_ : d_v_));
+            result.bound   = py::cast<py::tuple>(value[0]);
+            result.need    = py::cast<int64_t>(value[1]);
+            result.extent0 = result.shape[0];
+        } else {
+            auto value     = py::cast<py::tuple>(dense_layout_(shape_tuple,
+                                                           stride_tuple,
+                                                           role == Q || role == O || role == Gate ? qh_ : kh_,
+                                                           role == Q || role == K ? d_qk_
+                                                               : role == O            ? d_v_ / output_pack_
+                                                                                      : d_v_,
+                                                           role == Q || role == O || role == Gate ? sq_ : sk_,
+                                                           b_,
+                                                           role == Gate ? 2 : dtype_bits_[role] / 8,
+                                                           role != O || split_ == 1,
+                                                           names[role],
+                                                           dense_flex_));
+            result.bound   = py::cast<py::tuple>(value[0]);
+            result.extent0 = py::cast<int64_t>(value[1]);
+            result.extent1 = py::cast<int64_t>(value[2]);
+            result.need    = py::cast<int64_t>(value[3]);
+        }
+        result.valid = true;
+        cached       = result;
+        return result;
+    }
+    BoundGeometry
+    geometry(const NativeOperandView &f, size_t role) {
+        auto result = layout(f, role);
+        if (quantized_ && paged_ && (role == K || role == V) && f.observed_bytes >= 0 &&
+            f.observed_bytes / (dtype_bits_[role] / 8) < result.need)
+            invalid(std::string(names[role]) + ": page pool spans " +
+                    std::to_string(f.observed_bytes / (dtype_bits_[role] / 8)) +
+                    " elements; its effective geometry needs " + std::to_string(result.need));
+        check_span(f, result.need, role);
+        return result;
+    }
+    BoundGeometry
+    table(const NativeOperandView &f, size_t role, int64_t b) {
+        operand(f, role, kDLInt, 32, 4);
+        if (!f.pointer) invalid(std::string(names[role]) + " must have a non-null address");
+        auto result = layout(f, role, b);
+        check_span(f, result.need, role);
+        return result;
+    }
+    int64_t
+    packed_capacity(const NativeOperandView &f, const BoundGeometry &g, size_t role) const {
+        if (f.observed_bytes < 0 && role != LSE)
+            invalid(std::string(names[role]) + " was passed as a bare address; a ragged operand needs a sized buffer");
+        const int64_t available = f.observed_bytes < 0 ? -1 : f.observed_bytes / (role == LSE ? 4 : 2);
+        const auto token_stride = py::cast<int64_t>(g.bound[role == LSE ? 2 : 1]);
+        int64_t cap             = available < 0        ? std::numeric_limits<int32_t>::max()
+                                  : available < g.need ? 0
+                                                       : add((available - g.need) / token_stride, 1);
+        if (role == LSE && g.extent0) cap = std::min(cap, g.extent1);
+        return cap;
+    }
+    int64_t
+    offsets(const NativeOperandView &f, size_t role) const {
+        operand(f, role, kDLInt, offset_bits_, offset_bits_ / 8);
+        return integer_vector(f, role, add(b_, 1));
+    }
+    int64_t
+    lengths(const NativeOperandView &f, size_t role, int64_t b) const {
+        operand(f, role, kDLInt, 32, 4);
+        return integer_vector(f, role, b);
+    }
+    static int64_t
+    contiguous_elements(const NativeOperandView &f, size_t role) {
+        if (!f.stride.empty() && f.stride.size() != f.shape.size())
+            invalid("operand shape and stride must have the same rank");
+        int64_t n = 1;
+        for (size_t i = f.shape.size(); i-- > 0;) {
+            if (!f.stride.empty() && f.shape[i] != 1 && f.stride[i] != n)
+                invalid(std::string(names[role]) + " must be contiguous");
+            n = multiply(n, f.shape[i]);
+        }
+        return n;
+    }
+    static int64_t
+    integer_vector(const NativeOperandView &f, size_t role, int64_t b) {
+        if (contiguous_elements(f, role) < b) invalid(std::string(names[role]) + " has too few elements for this plan");
+        check_span(f, b, role);
+        return f.pointer;
+    }
+    void
+    put(py::list &frame, Slot slot, py::object value) const {
+        frame[index_[slot]] = std::move(value);
+    }
+    py::object fn_, owner_, dense_layout_, pool_layout_, table_layout_, lse_layout_;
+    py::object combine_fn_, combine_owner_, fill_word_;
+    bool quantized_ = false, has_amax_ = false, pv_bf16_ = false;
+    int64_t quant_offset_ = 0;
+    bool block_output_ = false, block_has_scale_ = false;
+    bool has_gate_       = false;
+    int gate_code_       = kDLBfloat;
+    int64_t block_bytes_ = 0, output_pack_ = 1;
+    size_t block_index_ = 0;
+    std::array<size_t, 5> quant_indices_;
+    std::unique_ptr<SdpaMxScaleBinding> mx_scales_;
+    py::object packed_layout_, ragged_lse_layout_;
+    py::tuple ragged_divs_;
+    py::tuple partial_o_strides_, partial_lse_strides_;
+    py::tuple template_;
+    std::array<size_t, NumSlots> index_;
+    std::array<int, 4> dtype_code_, dtype_bits_;
+    std::array<Geometry, NumRoles> geometry_;
+    int64_t b_, qh_, kh_, d_qk_, d_v_, sq_, sk_, device_, page_size_, tile_n_, window_right_;
+    int64_t split_, lse_offset_ = 0, workspace_bytes_ = 0;
+    int64_t total_q_ = 0;
+    int offset_bits_ = 32;
+    bool ragged_, has_total_q_ = false, ragged_lse_head_major_ = false;
+    int64_t ragged_q_lens_ = 0;
+    bool paged_, hnd_, v_hnd_, has_lse_, has_sink_, seq_kv_, seq_q_, shape_fixed_, lpt_fixed_, tail_native_, causal_,
+        bottom_right_, fp32_partial_, dense_flex_;
+    bool combine_q_lens_ = false;
+};
+}  // namespace
+void
+init_sdpa_dense_binding(py::module_ &m) {
+    py::class_<SdpaDenseBinder>(m, "_SdpaDenseBinder")
+        .def(py::init<const py::object &>(), py::arg("spec"))
+        // The epilogue gate roles the Python side reads before building a gated spec (typed declines on an older
+        // extension): the gate over dense K/V, and the gate over PAGED pools (the shared SM100 d256 half body compiled
+        // for cc 10.7).
+        .def_prop_ro_static("supports_epilogue_gate", [](py::object) { return true; })
+        .def_prop_ro_static("supports_paged_epilogue_gate", [](py::object) { return true; })
+        // The split sink combine takes the per-batch Q lengths (python: SplitCombineSpec /
+        // DenseLaunchSpec.combine_q_lens).
+        .def_prop_ro_static("supports_combine_q_lens", [](py::object) { return true; })
+        .def_prop_ro_static("supports_ragged_q_lens", [](py::object) { return true; })
+        .def_prop_ro_static("supports_quantized_split_sink", [](py::object) { return true; })
+        .def_prop_ro_static("supports_native_d576", [](py::object) { return true; })
+        .def_prop_ro_static("supports_mixed_fp8_kv", [](py::object) { return true; })
+        .def("bind", &SdpaDenseBinder::bind, py::arg("pack"), py::arg("indices"), py::arg("stream"))
+        .def("bind_split",
+             &SdpaDenseBinder::bind_split,
+             py::arg("pack"),
+             py::arg("indices"),
+             py::arg("workspace"),
+             py::arg("stream"))
+        .def("bind_quantized",
+             &SdpaDenseBinder::bind_quantized,
+             py::arg("pack"),
+             py::arg("indices"),
+             py::arg("workspace"),
+             py::arg("stream"))
+        .def("execute",
+             &SdpaDenseBinder::execute,
+             py::arg("pack"),
+             py::arg("indices"),
+             py::arg("stream"),
+             py::arg("scale_softmax_log2") = py::none(),
+             py::arg("workspace")          = 0)
+        .def("execute_ordered",
+             &SdpaDenseBinder::execute_ordered,
+             py::arg("schema"),
+             py::arg("buffers"),
+             py::arg("tensor_uids"),
+             py::arg("auto_bindings"),
+             py::arg("workspace").none(),
+             py::arg("override_uids").none(),
+             py::arg("override_shapes").none(),
+             py::arg("override_strides").none(),
+             py::arg("indices"),
+             py::arg("stream"));
+}
