+    }
+
+   private:
+    [[noreturn]] static void
+    invalid(const std::string &message) {
+        throw nanobind::value_error(("cudnn.sdpa: " + message).c_str());
+    }
+    static int64_t
+    multiply(int64_t a, int64_t b) {
