+            const auto n = f.shape[i], stride = f.stride.empty() ? compact : f.stride[i];
+            if (n < 0 || stride < 0) invalid("MXFP8 scale geometry must be nonnegative");
+            empty |= n == 0;
+            if (n > 1) dimensions.emplace_back(stride, n);
+            compact = multiply(compact, n);
+        }
