+    }
+    const std::array<const char *, 4> names_ = {"sf_q_ptr", "sf_k_ptr", "sf_v_ptr", "sf_tiles"};
+    std::array<size_t, 4> indices_;
+    std::vector<int64_t> sizes_;
+    std::array<int64_t, 3> heads_;
+    int64_t device_;
+};
