+             py::arg("indices"),
+             py::arg("stream"),
+             py::arg("scale").none(),
+             py::arg("overridden"),
+             py::arg("raw_storage"))
+        .def("execute",
+             &SdpaSm80FwdBinder::execute,
+             py::arg("pack"),
+             py::arg("indices"),
+             py::arg("stream"),
+             py::arg("scale").none(),
+             py::arg("overridden"),
+             py::arg("raw_storage"));
