+          fn_(spec.attr("fn")),
+          owner_(spec.attr("artifact")),
+          n_seq_(py::cast<int64_t>(spec.attr("n_seq"))),
+          has_sink_(py::cast<bool>(spec.attr("has_sink"))) {
