+        if (facts[2].shape[1] != tkv || facts[3].shape[1] != tq) invalid("packed token capacities must agree");
+        if (facts[4].shape[0] != 1 || facts[4].shape[1] != h_ || facts[4].shape[2] != tq)
+            invalid("Stats must be [1,Hq,Tq]");
