+init_sdpa_sm80_thd_binding(py::module_ &m) {
+    py::class_<SdpaSm80ThdBinder>(m, "_SdpaSm80ThdBinder")
+        .def(py::init<const py::object &>())
+        .def("bind", &SdpaSm80ThdBinder::bind)
+        .def("execute", &SdpaSm80ThdBinder::execute);
