+    plans.set_max_shared_mem_allowed(0);
+    REQUIRE(plans.get_max_shared_mem_allowed() == 0);
+    plans.set_max_shared_mem_allowed(98 * 1024);
+    REQUIRE(plans.get_max_shared_mem_allowed() == 98 * 1024);
+}

